INSERT INTO products (id, name, slug, summary, content, brand, price, featured_image, category_id, supplier_id) VALUES
(1, 'iPhone 15 Pro Max', 'iphone-15-pro-max', 'iPhone 15 Pro Max - sản phẩm chính hãng hàng đầu, bảo hành 12 tháng, ưu đãi đặc quyền.', 'Chi tiết về iPhone 15 Pro Max: Sản phẩm sở hữu thiết kế đột phá, cấu hình đỉnh cao và chất lượng vượt trội. Thích hợp sử dụng học tập, làm việc, thể thao hay thời trang hàng ngày. Đầy đủ phụ kiện chính hãng đi kèm trong hộp.', 'Apple', 30000000, 'https://images.unsplash.com/photo-1695048133142-1a20484d2569?q=80&w=400', 4, 1),
(2, 'iPhone 14 Pro', 'iphone-14-pro', 'iPhone 14 Pro - sản phẩm chính hãng hàng đầu, bảo hành 12 tháng, ưu đãi đặc quyền.', 'Chi tiết về iPhone 14 Pro: Sản phẩm sở hữu thiết kế đột phá, cấu hình đỉnh cao và chất lượng vượt trội. Thích hợp sử dụng học tập, làm việc, thể thao hay thời trang hàng ngày. Đầy đủ phụ kiện chính hãng đi kèm trong hộp.', 'Apple', 25000000, 'https://cdn2.cellphones.com.vn/200x/media/catalog/product/i/p/iphone-14-pro_2__4.png', 4, 1),
 (3, 'iPad Pro M2 11 inch', 'ipad-pro-m2-11-inch', 'iPad Pro M2 11 inch - sản phẩm chính hãng hàng đầu, bảo hành 12 tháng, ưu đãi đặc quyền.', 'Chi tiết về iPad Pro M2 11 inch: Sản phẩm sở hữu thiết kế đột phá, cấu hình đỉnh cao và chất lượng vượt trội. Thích hợp sử dụng học tập, làm việc, thể thao hay thời trang hàng ngày. Đầy đủ phụ kiện chính hãng đi kèm trong hộp.', 'Apple', 20000000, 'https://images.unsplash.com/photo-1544244015-0df4b3ffc6b0?q=80&w=400', 22, 1),
 (4, 'Apple Watch Ultra 2', 'apple-watch-ultra-2', 'Apple Watch Ultra 2 - sản phẩm chính hãng hàng đầu, bảo hành 12 tháng, ưu đãi đặc quyền.', 'Chi tiết về Apple Watch Ultra 2: Sản phẩm sở hữu thiết kế đột phá, cấu hình đỉnh cao và chất lượng vượt trội. Thích hợp sử dụng học tập, làm việc, thể thao hay thời trang hàng ngày. Đầy đủ phụ kiện chính hãng đi kèm trong hộp.', 'Apple', 22000000, 'https://images.unsplash.com/photo-1434494878577-86c23bcb06b9?q=80&w=400', 24, 1),
(5, 'iMac 24 inch M3', 'imac-24-inch-m3', 'iMac 24 inch M3 - sản phẩm chính hãng hàng đầu, bảo hành 12 tháng, ưu đãi đặc quyền.', 'Chi tiết về iMac 24 inch M3: Sản phẩm sở hữu thiết kế đột phá, cấu hình đỉnh cao và chất lượng vượt trội. Thích hợp sử dụng học tập, làm việc, thể thao hay thời trang hàng ngày. Đầy đủ phụ kiện chính hãng đi kèm trong hộp.', 'Apple', 35000000, 'https://images.unsplash.com/photo-1527443224154-c4a3942d3acf?q=80&w=400', 4, 1),
(6, 'Apple AirTag 4 Pack', 'apple-airtag-4-pack', 'Apple AirTag 4 Pack - sản phẩm chính hãng hàng đầu, bảo hành 12 tháng, ưu đãi đặc quyền.', 'Chi tiết về Apple AirTag 4 Pack: Sản phẩm sở hữu thiết kế đột phá, cấu hình đỉnh cao và chất lượng vượt trội. Thích hợp sử dụng học tập, làm việc, thể thao hay thời trang hàng ngày. Đầy đủ phụ kiện chính hãng đi kèm trong hộp.', 'Apple', 2500000, 'https://images.unsplash.com/photo-1629126786844-3453b34208a0?q=80&w=400', 4, 1),
 (7, 'AirPods Max Silver', 'airpods-max-silver', 'AirPods Max Silver - sản phẩm chính hãng hàng đầu, bảo hành 12 tháng, ưu đãi đặc quyền.', 'Chi tiết về AirPods Max Silver: Sản phẩm sở hữu thiết kế đột phá, cấu hình đỉnh cao và chất lượng vượt trội. Thích hợp sử dụng học tập, làm việc, thể thao hay thời trang hàng ngày. Đầy đủ phụ kiện chính hãng đi kèm trong hộp.', 'Apple', 13000000, 'https://images.unsplash.com/photo-1613040809024-b4ef7ba99bc3?q=80&w=400', 26, 1),
