-- === ĐIỆN THOẠI MỚI (106-125) ===
(106, 'iPhone 17 Pro Max', 'iphone-17-pro-max', 'iPhone 17 Pro Max - Camera Array siêu mỏng, chip A19 Pro, RAM 12GB.', 'iPhone 17 Pro Max sở hữu thiết kế Camera Array mỏng nhất từ trước đến nay, chip A19 Pro 3nm thế hệ 2, màn hình OLED ProMotion 120Hz, pin dung lượng lớn hơn 20%. Hỗ trợ Apple Intelligence, Siri thông minh hơn.', 'Apple', 36990000, 'https://cdn2.cellphones.com.vn/200x/media/catalog/product/i/p/iphone-17-pro-max_3.jpg', 4, 1),
(107, 'iPhone 17 Pro', 'iphone-17-pro', 'iPhone 17 Pro - Titan Desert, camera 48MP hệ thống 3 ống kính tiên tiến.', 'iPhone 17 Pro với thiết kế titan sa mạc sang trọng, camera 48MP Triple với ống kính tiềm vọng thế hệ mới, chip A19 Pro, màn hình 6.3 inch OLED siêu mỏng chỉ 7.8mm.', 'Apple', 29990000, 'https://cdn2.cellphones.com.vn/200x/media/catalog/product/i/p/iphone-17-pro-max-1_4.jpg', 4, 1),
(108, 'Samsung Galaxy S25 Ultra', 'samsung-galaxy-s25-ultra', 'Galaxy S25 Ultra - S Pen tích hợp AI, Snapdragon 8 Elite, màn hình 6.9 inch.', 'Samsung Galaxy S25 Ultra nâng cấp S Pen với AI hỗ trợ viết tay, chip Snapdragon 8 Elite for Galaxy, RAM 12GB, camera 200MP, pin 5000mAh sạc nhanh 45W.', 'Samsung', 33990000, 'https://cdn2.cellphones.com.vn/200x/media/catalog/product/s/a/samsung-galaxy-s25-ultra_1_.jpg', 5, 2),
(109, 'Samsung Galaxy S25+', 'samsung-galaxy-s25-plus', 'Galaxy S25+ - Snapdragon 8 Elite, màn hình 6.7 inch Dynamic AMOLED 2X.', 'Galaxy S25+ với chip Snapdragon 8 Elite mạnh mẽ, màn hình 6.7 inch Dynamic AMOLED 2X 120Hz, RAM 12GB, camera 50MP, thiết kế mỏng nhẹ chỉ 7.3mm.', 'Samsung', 26990000, 'https://cdn2.cellphones.com.vn/200x/media/catalog/product/s/a/samsung-galaxy-s25_1_.jpg', 5, 2),
(110, 'Samsung Galaxy Z Fold 6', 'samsung-galaxy-z-fold-6', 'Galaxy Z Fold 6 - Gập mỏng nhất, AI tích hợp sâu, Galaxy AI đa tác vụ.', 'Samsung Galaxy Z Fold 6 thiết kế gập mỏng 12.1mm khi đóng, màn hình trong 7.6 inch AMOLED, chip Snapdragon 8 Gen 3, Galaxy AI với tính năng phiên dịch trực tiếp.', 'Samsung', 42990000, 'https://cdn2.cellphones.com.vn/200x/media/catalog/product/s/a/samsung-galaxy-z-fold-6_1_.jpg', 5, 2),
(111, 'Samsung Galaxy Z Flip 6', 'samsung-galaxy-z-flip-6', 'Galaxy Z Flip 6 - Gập nhỏ gọn, màn hình nắp 3.4 inch, pin 4000mAh.', 'Galaxy Z Flip 6 với FlexWindow 3.4 inch phong phú hơn, chip Snapdragon 8 Gen 3, pin 4000mAh tăng 58% so với đời trước, camera 50MP, thiết kế đa dạng màu sắc.', 'Samsung', 22990000, 'https://cdn2.cellphones.com.vn/200x/media/catalog/product/s/a/samsung-galaxy-z-flip6_1_.jpg', 5, 2),
(112, 'Xiaomi 15 Ultra', 'xiaomi-15-ultra', 'Xiaomi 15 Ultra - Leica camera 200W sạc siêu nhanh, chip Snapdragon 8 Elite.', 'Xiaomi 15 Ultra với hệ thống camera Leica 5 ống kính, sạc nhanh 200W HyperCharge, Snapdragon 8 Elite, RAM 16GB LPDDR5X, màn hình AMOLED 6.73 inch 144Hz.', 'Xiaomi', 30990000, 'https://cdn2.cellphones.com.vn/200x/media/catalog/product/x/i/xiaomi-15-ultra_1_.jpg', 35, 5),
(113, 'Oppo Find X8 Ultra', 'oppo-find-x8-ultra', 'Find X8 Ultra - Hasselblad camera, chip Dimensity 9400, mỏng 8.9mm.', 'OPPO Find X8 Ultra với camera Hasselblad tuned, chip MediaTek Dimensity 9400 đỉnh cao, sạc nhanh 100W, pin 5910mAh, màn hình AMOLED 6.82 inch 120Hz.', 'Oppo', 28990000, 'https://cdn2.cellphones.com.vn/200x/media/catalog/product/o/p/oppo-find-x8-ultra_1_.jpg', 37, 5),
(114, 'Vivo X200 Ultra', 'vivo-x200-ultra', 'Vivo X200 Ultra - Zeiss camera 200MP, chip Dimensity 9400, pin 6000mAh.', 'Vivo X200 Ultra hợp tác Zeiss với camera 200MP periscope, chip Dimensity 9400, sạc nhanh 90W, pin 6000mAh dung lượng siêu lớn, màn hình LTPO AMOLED 6.82 inch.', 'Vivo', 27990000, 'https://cdn2.cellphones.com.vn/200x/media/catalog/product/v/i/vivo-x200-ultra_1_.jpg', 41, 5),
(115, 'Google Pixel 9 Pro XL', 'google-pixel-9-pro-xl', 'Pixel 9 Pro XL - Google AI tốt nhất, chip Tensor G4, camera 50MP Ultra Wide.', 'Google Pixel 9 Pro XL với chip Tensor G4 tự phát triển, tích hợp Gemini AI sâu nhất, camera 50MP + 48MP Ultra Wide + 48MP Telephoto, màn hình LTPO OLED 6.8 inch.', 'Google', 28990000, 'https://cdn2.cellphones.com.vn/200x/media/catalog/product/g/o/google-pixel-9-pro-xl_1_.jpg', 38, 5),
(116, 'Nothing Phone (3)', 'nothing-phone-3', 'Nothing Phone (3) - Glyph Interface độc đáo, Snapdragon 8s Gen 3.', 'Nothing Phone (3) với hệ thống Glyph Interface phát triển hơn, chip Snapdragon 8s Gen 3, camera 50MP + 50MP góc rộng, pin 5000mAh, thiết kế kính trong suốt độc đáo.', 'Nothing', 16990000, 'https://cdn2.cellphones.com.vn/200x/media/catalog/product/n/o/nothing-phone-3_1_.jpg', 41, 5),
(117, 'Motorola Edge 60 Pro', 'motorola-edge-60-pro', 'Motorola Edge 60 Pro - sạc 125W, OLED 4K, MediaTek Dimensity 9200+.', 'Motorola Edge 60 Pro với màn hình pOLED 6.7 inch 165Hz, sạc siêu nhanh 125W TurboPower, chip Dimensity 9200+, RAM 12GB, camera 50MP chống rung OIS mạnh.', 'Motorola', 14990000, 'https://cdn2.cellphones.com.vn/200x/media/catalog/product/m/o/motorola-edge-60-pro_1_.jpg', 41, 5),
(118, 'Realme GT 7 Pro', 'realme-gt-7-pro', 'Realme GT 7 Pro - Snapdragon 8 Elite đầu tiên, sạc 120W, pin 6500mAh.', 'Realme GT 7 Pro là điện thoại đầu tiên dùng Snapdragon 8 Elite, sạc siêu tốc 120W SuperVOOC, pin 6500mAh khổng lồ, camera 50MP Sony IMX906, màn hình AMOLED 6.78 inch.', 'Realme', 19990000, 'https://cdn2.cellphones.com.vn/200x/media/catalog/product/r/e/realme-gt-7-pro_1_.jpg', 41, 5),
(119, 'Honor Magic 7 Pro', 'honor-magic-7-pro', 'Honor Magic 7 Pro - AI camera, Snapdragon 8 Elite, sạc 100W không dây.', 'Honor Magic 7 Pro với chip Snapdragon 8 Elite, AI Enhanced Camera 200MP, sạc không dây 100W nhanh nhất phân khúc, pin 5850mAh, màn hình AMOLED 6.8 inch 120Hz.', 'Honor', 22990000, 'https://cdn2.cellphones.com.vn/200x/media/catalog/product/h/o/honor-magic-7-pro_1_.jpg', 42, 5),
